export type ClientGraphSubType =
  | 'character_skill'
  | 'character_control_skill'
  | 'creation_skill'
  | 'creation_status'
  | 'creation_status_decision'
  | 'bool_filter'
  | 'int_filter'

export type ClientSpecialKind =
  | 'start'
  | 'signal'
  | 'structure'
  | 'structure_list'
  | 'local_variable'
  | 'dict'
  | 'reflect'
  | 'multiple_branches'
  | 'inline_var_type_hint'
  | 'structure_list_unknown_binding'

export type ClientPinMetadata = {
  index: number
  kind: 'input' | 'output' | 'in_flow' | 'out_flow' | 'client_exec' | 'client_signal'
  type: string
  reflective?: boolean
  indexOfConcrete?: number
  clientVarType?: number
  /** explicit editor default decoded from the static Node protobuf */
  defaultValue?: number | string | boolean | [number, number, number]
  /** editor i2 index when it differs from i1 (static Node protobuf evidence) */
  i2Index?: number
  /** whether the editor exposes a connection socket for this input */
  connectable?: boolean
  /** exact editor connection type; enum pins use their enum class id */
  connectionType?: number
}

export type ClientNodeMetadata = {
  subType: ClientGraphSubType
  nodeType: string
  displayName: string
  graphType: number
  genericId: number
  /** null when the node has multiple concrete variants (see reflectMap) */
  concreteId: number | string | null
  inputs: ClientPinMetadata[]
  outputs: ClientPinMetadata[]
  flows?: ClientPinMetadata[]
  /**
   * physical input pin index per public method arg (codegen-derived from doc
   * alignment). Absent when identity; hidden pins (e.g. leading selector
   * enums) keep their editor defaults and are skipped by this mapping.
   */
  argPins?: number[]
  reflectMap?: Array<{
    concreteId: number | string
    variantKey: string
    pins?: ClientPinMetadata[]
  }>
  pinFlags?: string[]
  specialKind?: ClientSpecialKind
  isStart?: boolean
  isSignal?: boolean
  isStructure?: boolean
  isLocalVariable?: boolean
  isDict?: boolean
  /** observed GraphNode.contextDeclaration payload, e.g. begins nodes in skill graphs */
  contextDeclaration?: { kind: number; index: number }
  sampleFile: string
}

